import fs from 'node:fs';
const pages=[
 {file:'guides/occasions/ethiopian-holiday-foods.html',description:'Ethiopian holiday foods explained through doro wat, injera, shiro, niter kibbeh and the shared-table traditions surrounding celebration meals.',faq:[['What foods are served for Ethiopian holidays?','Menus vary by family, region and religious practice, but celebratory tables may include injera with stews such as doro wat, vegetable or pulse dishes, and aromatic niter kibbeh.'],['Is doro wat eaten for Ethiopian holidays?','Doro wat is strongly associated with important gatherings and holidays in many Ethiopian households, though it is not the only celebratory dish and menus vary.'],['What is served with doro wat?','Injera is the central accompaniment, used to share and eat the stew. A larger spread may include shiro and vegetable dishes.']],main:`<main class="section region-page"><section class="page-hero"><span class="eyebrow">Occasion guide</span><h1>Ethiopian Holiday Foods</h1><p>Ethiopian celebration meals often center on a shared platter of injera and carefully prepared stews, with the exact table shaped by family, region, faith and occasion.</p></section><section class="recipe-section"><h2>Foods that anchor a celebration table</h2><p>No single menu represents every Ethiopian holiday meal. Christmas, Easter, Meskel, weddings and family gatherings follow different calendars and household traditions. What they often share is generosity: several preparations arranged on injera and eaten communally rather than isolated as separate courses.</p><div class="essential-grid"><a class="essential-card" href="../../recipes/ethiopian-doro-wat.html"><strong>Doro Wat</strong><span>Chicken and eggs in a deeply reduced onion and berbere sauce, strongly associated with important gatherings.</span><b>Cook →</b></a><a class="essential-card" href="../../subrecipes/ethiopian-injera.html"><strong>Ethiopian Injera</strong><span>The fermented flatbread that supports the shared platter and absorbs the stews.</span><b>Make →</b></a><a class="essential-card" href="../../recipes/shiro-wot.html"><strong>Shiro Wot</strong><span>A smooth chickpea-flour stew that can appear in everyday meals, fasting spreads and larger assortments.</span><b>Cook →</b></a><a class="essential-card" href="../../subrecipes/ethiopian-niter-kibbeh.html"><strong>Niter Kibbeh</strong><span>Aromatic spiced clarified butter used to build depth in many non-fasting dishes.</span><b>Make →</b></a></div></section><section class="recipe-section"><h2>How the dishes work together</h2><p>Injera is not a side placed beside the meal. It is the eating surface, utensil and sour counterpoint to rich stews. Doro wat brings chile heat and concentrated onion flavor. Shiro contributes a softer pulse-based texture, while vegetable dishes can vary the color, bitterness and freshness of the platter.</p><p>Fasting practice matters when planning an Ethiopian table. Orthodox fasting meals exclude meat and animal products, so a fasting holiday or guest may call for pulse and vegetable dishes prepared without niter kibbeh. Confirm the occasion and the diners rather than assuming one celebratory menu fits every table.</p></section><section class="recipe-section"><h2>Planning a practical Fringe Table menu</h2><ol class="method-list detailed-static"><li><strong>1.</strong><span>Make niter kibbeh in advance if the menu includes non-fasting dishes.</span></li><li><strong>2.</strong><span>Begin doro wat early; the onions need patient reduction and the finished stew benefits from a short rest.</span></li><li><strong>3.</strong><span>Prepare injera according to its fermentation schedule rather than treating it as a last-minute bread.</span></li><li><strong>4.</strong><span>Add one pulse or vegetable dish so every diner is not relying on the richest stew.</span></li><li><strong>5.</strong><span>Arrange foods in separate portions on injera and replenish the bread as the meal continues.</span></li></ol><p class="story-caveat">These pages are starting points for home cooks. For a specific religious or family celebration, follow the knowledge and preferences of the people hosting and eating the meal.</p></section><section class="recipe-section"><h2>Frequently asked questions</h2><h3>What foods are served for Ethiopian holidays?</h3><p>Menus vary, but injera, carefully prepared stews, pulse dishes and vegetables often form a shared spread.</p><h3>Is doro wat eaten for Ethiopian holidays?</h3><p>It is strongly associated with important gatherings in many households, while fasting occasions require meatless alternatives.</p><h3>What is served with doro wat?</h3><p>Injera is essential. Shiro and vegetable preparations can turn the stew into a more varied communal meal.</p></section></main>`},
 {file:'guides/serve-with/what-to-serve-with-momos.html',description:'What to serve with momos: tomato-chile achar, light broth, crisp vegetables and practical menu combinations that keep Nepali dumplings central.',faq:[['What sauce is served with momos?','A sharp tomato-and-chile achar is a classic partner. Timur pepper may add a citrusy, numbing aroma in Nepali versions.'],['Can momos be a complete meal?','Yes. A generous portion with achar can stand alone, or it can be paired with a light broth and simple vegetables.'],['What side dishes go with momos?','Choose light, acidic or crisp sides rather than several heavy dishes so the dumplings and their filling remain the focus.']],main:`<main class="section region-page"><section class="page-hero"><span class="eyebrow">Serving guide</span><h1>What to Serve With Momos</h1><p>Momos can be a snack or a full meal. A sharp tomato-chile achar is the essential partner; broth and crisp vegetables can round out the table without overwhelming the dumplings.</p></section><section class="recipe-section"><h2>The best first pairing: momo achar</h2><div class="essential-grid"><a class="essential-card" href="../../subrecipes/nepali-tomato-chile-chutney.html"><strong>Nepali Tomato-Chile Chutney</strong><span>Tomato, chile and aromatics make the bright, savory dip most directly associated with the dumplings.</span><b>Make →</b></a><a class="essential-card" href="../../recipes/nepali-momos.html"><strong>Nepali Chicken Momos</strong><span>The complete steamed-dumpling recipe, including folding and doneness checkpoints.</span><b>Cook →</b></a><a class="essential-card" href="../ingredients/what-is-timur-pepper.html"><strong>What Is Timur Pepper?</strong><span>Understand the citrusy, tingling spice that can distinguish Nepali achar.</span><b>Read →</b></a></div><p>Serve the achar in a wide bowl so each dumpling can be dipped or spooned with sauce. Its acidity and chile cut through the juicy filling and soft wrapper. If your achar is especially hot, offer a milder portion rather than diluting the entire batch.</p></section><section class="recipe-section"><h2>Build a larger momo meal</h2><div class="prep-grid"><div><strong>Light broth</strong><p>A clear vegetable or chicken broth adds warmth without competing with the dumpling filling.</p></div><div><strong>Crisp vegetables</strong><p>A lightly dressed cucumber, cabbage or radish salad provides texture and acidity.</p></div><div><strong>Simple greens</strong><p>Quickly cooked greens with restrained seasoning balance a plate of steamed or fried momos.</p></div></div><p>Avoid crowding the table with several rich curries and fried sides. Momos already combine dough and a seasoned filling; the supporting dishes work best when they add contrast.</p></section><section class="recipe-section"><h2>Three practical menus</h2><ul><li><strong>Snack:</strong> momos and tomato-chile achar.</li><li><strong>Weeknight meal:</strong> momos, achar and a clear broth.</li><li><strong>Shared table:</strong> momos, two heat levels of achar, broth and a crisp vegetable salad.</li></ul><p>Steam the momos last. Achar can be prepared earlier, and broth can stay warm while the dumplings cook. Serve momos as soon as their wrappers are tender and the filling reaches a safe temperature.</p></section><section class="recipe-section"><h2>Frequently asked questions</h2><h3>What sauce is served with momos?</h3><p>A tomato-and-chile achar is the clearest starting point. Nepali versions may include sesame, cilantro or timur depending on the cook.</p><h3>Can momos be a complete meal?</h3><p>Yes. Increase the portion and add broth or vegetables only when the meal needs more volume or contrast.</p><h3>What side dishes go with momos?</h3><p>Light broth, crisp salad and simply cooked vegetables complement momos without hiding their filling and dipping sauce.</p></section></main>`}
];
for(const page of pages){let html=fs.readFileSync(page.file,'utf8');html=html.replace(/<meta name="description" content="[^"]*">/,`<meta name="description" content="${page.description}">`).replace(/<main[\s\S]*?<\/main>/,page.main);const schema={"@context":"https://schema.org","@type":"FAQPage",mainEntity:page.faq.map(([name,text])=>({"@type":"Question",name,acceptedAnswer:{"@type":"Answer",text}}))};html=html.replace('</head>',`<script type="application/ld+json">${JSON.stringify(schema)}</script></head>`);fs.writeFileSync(page.file,html)}
let sitemap=fs.readFileSync('sitemap.xml','utf8');for(const page of pages){const url=`https://fringetable.com/${page.file}`;sitemap=sitemap.replace(new RegExp(`(<loc>${url.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')}</loc><lastmod>)[^<]+`),`$12026-09-16`)}fs.writeFileSync('sitemap.xml',sitemap);
